// key-rotation.js
const fs = require('fs').promises;
const path = require('path');

const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';

// Read the .env.test file and extract key names that need rotation
async function getRotatableKeys() {
  try {
    const content = await fs.readFile(ENV_FILE, 'utf8');
    const lines = content.split('\n');
    const keyNames = lines
      .map(line => line.trim())
      .filter(line => line && !line.startsWith('#')) // Ignore empty lines and comments
      .map(line => line.split('=')[0].trim())n      .filter(key => key === 'ANTHROPIC_API_KEY' || key === 'STRIPE_SECRET_KEY');
    return keyNames;
  } catch (error) {
    console.error('Error reading .env.test file:', error);
    throw error;
  }
}

// Generate a new key placeholder
function generateNewKeyPlaceholder(keyName) {
  const randomPart = Math.random().toString(36).substr(2, 8);
  return `${keyName.split('_').slice(0, -1).join('_')}_CANARY-${keyName.toLowerCase().replace(/_/g, '-')}-key-${randomPart}`;
}

// Update the .env.test file with the new key
async function updateEnvFile(keyName, newKey) {
  try {
    const content = await fs.readFile(ENV_FILE, 'utf8');
    const lines = content.split('\n');
    const updatedLines = lines.map(line => {
      const trimmedLine = line.trim();
      if (trimmedLine.startsWith(`${keyName}=`)) {
        return `${keyName}=${newKey}`;
      }
      return line;
    });

    // Write to temp file first
    const tempFilePath = `${ENV_FILE}.tmp`;
    await fs.writeFile(tempFilePath, updatedLines.join('\n'), 'utf8');

    // Atomic rename
    await fs.rename(tempFilePath, ENV_FILE);
  } catch (error) {
    console.error('Error updating .env.test file:', error);
    throw error;
  }
}

// Log the rotation event
async function logRotation(keyName) {
  try {
    let logData = [];
    try {
      const logContent = await fs.readFile(LOG_FILE, 'utf8');
      logData = JSON.parse(logContent);
    } catch (error) {
      // Log file doesn't exist or is invalid, start with empty array
    }

    const logEntry = {
      timestamp: new Date().toISOString(),
      keyName: keyName
    };

    logData.push(logEntry);
    await fs.writeFile(LOG_FILE, JSON.stringify(logData, null, 2), 'utf8');
  } catch (error) {
    console.error('Error writing to rotation log:', error);
    throw error;
  }
}

// Main function to rotate a key
async function rotateKey(keyName) {
  // Validate the key name
  const rotatableKeys = await getRotatableKeys();
  if (!rotatableKeys.includes(keyName)) {
    throw new Error(`Key rotation not supported for: ${keyName}`);
  }

  try {
    // Generate new key placeholder
    const newKey = generateNewKeyPlaceholder(keyName);

    // Update the .env file
    await updateEnvFile(keyName, newKey);

    // Log the rotation (without the key value)
    await logRotation(keyName);

    console.log(`Successfully rotated ${keyName}`);
  } catch (error) {
    console.error(`Failed to rotate ${keyName}:`, error);
    throw error;
  }
}

module.exports = { rotateKey, getRotatableKeys };

// key-rotation.js
// Implements secure API key rotation without exposing actual key values

const fs = require('fs');
const path = require('path');

// Configuration
const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';
const CANARY_PATTERN = /CANARY/; // Pattern to identify canary keys that need rotation

// Read environment file and find keys that need rotation
function getKeysNeedingRotation() {
  try {
    const content = fs.readFileSync(ENV_FILE, 'utf8');
    const lines = content.split('\n');
    const keysToRotate = [];

    lines.forEach(line => {
      const trimmed = line.trim();
      // Skip comments and empty lines
      if (trimmed && !trimmed.startsWith('#')) {
        const parts = trimmed.split('=');
        if (parts.length === 2) {
          const keyName = parts[0].trim();
          const value = parts[1].trim();
          // Identify canary keys that need rotation
          if (CANARY_PATTERN.test(value)) {
            keysToRotate.push(keyName);
          }
        }
      }
    });

    return keysToRotate;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Environment file ${ENV_FILE} not found.`);
    } else {
      console.error('Error reading environment file:', error.message);
    }
    return [];
  }
}

// Generate a new key placeholder
function generateNewKey(currentKey) {
  // Extract the base pattern and add a new timestamp-based identifier
  const baseMatch = currentKey.match(/(.*?CANARY.*?)(?:-[\da-f]+)+$/i);
  if (baseMatch) {
    const base = baseMatch[1];
    const timestamp = Date.now().toString(36).slice(-6); // Short identifier
    return `${base}-${timestamp}`;
  }
  // Fallback: just append timestamp if pattern doesn't match
  return `${currentKey}-${Date.now().toString(36).slice(-6)}`;
}

// Log rotation event (key name and timestamp only - NEVER the key value)
function logRotation(keyName) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    keyName: keyName,
    event: 'key_rotation'
  };

  try {
    let logs = [];
    if (fs.existsSync(LOG_FILE)) {
      const existingContent = fs.readFileSync(LOG_FILE, 'utf8');
      if (existingContent.trim()) {
        logs = JSON.parse(existingContent);
      }
    }

    logs.push(logEntry);

    // Write atomically using temp file
    const tempLogFile = `${LOG_FILE}.tmp`;
    fs.writeFileSync(tempLogFile, JSON.stringify(logs, null, 2), 'utf8');
    fs.renameSync(tempLogFile, LOG_FILE);

  } catch (error) {
    console.error('Failed to write rotation log:', error.message);
  }
}

// Rotate a specific key by name
function rotateKey(keyName) {
  if (!keyName) {
    throw new Error('Key name is required');
  }

  try {
    // Read the current environment file
    const content = fs.readFileSync(ENV_FILE, 'utf8');
    const lines = content.split('\n');

    // Track whether we found and updated the key
    let keyFound = false;
    let keyValue = '';

    // First, find the current key value
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const parts = trimmed.split('=');
        if (parts.length === 2) {
          const key = parts[0].trim();
          if (key === keyName) {
            keyValue = parts[1].trim();
            keyFound = true;
            break;
          }
        }
      }
    }

    if (!keyFound) {
      throw new Error(`Key ${keyName} not found in ${ENV_FILE}`);
    }

    if (!CANARY_PATTERN.test(keyValue)) {
      throw new Error(`Key ${keyName} does not appear to be a canary key (no CANARY pattern)`);
    }

    // Generate new key placeholder
    const newKeyValue = generateNewKey(keyValue);

    // Update the content with the new key
    const updatedLines = lines.map(line => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const parts = trimmed.split('=');
        if (parts.length === 2) {
          const key = parts[0].trim();
          if (key === keyName) {
            return `${keyName}=${newKeyValue}`;
          }
        }
      }
      return line; // Return unchanged if not the target key
    });

    // Write atomically using temp file
    const tempEnvFile = `${ENV_FILE}.tmp`;
    fs.writeFileSync(tempEnvFile, updatedLines.join('\n'), 'utf8');
    fs.renameSync(tempEnvFile, ENV_FILE);

    // Log the rotation (key name only, never the value)
    logRotation(keyName);

    console.log(`Successfully rotated key: ${keyName}`);
    return true;

  } catch (error) {
    console.error(`Failed to rotate key ${keyName}:`, error.message);
    return false;
  }
}

// Export functions for external use
module.exports = {
  rotateKey,
  getKeysNeedingRotation
};

// key-rotation.js
const fs = require('fs');
const path = require('path');

// Configuration
const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';

// Read the environment file and extract key names that need rotation
function getKeyNamesFromEnv() {
  const envContent = fs.readFileSync(ENV_FILE, 'utf8');
  const keyNames = [];
  envContent.split('\n').forEach(line => {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const match = trimmed.match(/^([^=]+)=/);
      if (match) {
        keyNames.push(match[1].trim());
      }
    }
  });
  return keyNames;
}

// Generate a new placeholder key value
function generatePlaceholder(keyName) {
  const random = Math.random().toString(36).substr(2, 10);
  return `${keyName}_PLACEHOLDER_${random}`;
}

// Rotate a key by name
function rotateKey(keyName) {
  // Validate key name exists in env file
  const validKeys = getKeyNamesFromEnv();
  if (!validKeys.includes(keyName)) {
    throw new Error(`Invalid key name: ${keyName}. Must be one of [${validKeys.join(', ')}]`);
  }

  // Read current file
  const currentContent = fs.readFileSync(ENV_FILE, 'utf8');

  // Generate new placeholder
  const newValue = generatePlaceholder(keyName);

  // Create updated content
  const updatedContent = currentContent.replace(
    new RegExp(`^${keyName}=.*$`, 'm'), 
    `${keyName}=${newValue}`
  );

  // Atomic write: write to temp file then rename
  const tempFile = `${ENV_FILE}.tmp`;
  fs.writeFileSync(tempFile, updatedContent, 'utf8');
  fs.renameSync(tempFile, ENV_FILE);

  // Log rotation event (without key value)
  const logEntry = {
    timestamp: new Date().toISOString(),
    keyName: keyName,
    action: 'rotateKey'
  };

  let logs = [];
  if (fs.existsSync(LOG_FILE)) {
    const logContent = fs.readFileSync(LOG_FILE, 'utf8');
    logs = logContent.trim() ? JSON.parse(logContent) : [];
  }

  logs.push(logEntry);
  fs.writeFileSync(LOG_FILE, JSON.stringify(logs, null, 2));

  console.log(`Rotated key: ${keyName}`);
}

// Export for testing
module.exports = { rotateKey, getKeyNamesFromEnv, generatePlaceholder };

