// API Key Rotation Mechanism

const fs = require('fs');
const path = require('path');

const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';

// Read the current environment variables to determine which keys need rotation
function getKeysForRotation() {
  try {
    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const lines = envContent.split('\n');
    const keysToRotate = [];

    lines.forEach(line => {
      const match = line.trim().match(/^([A-Z_]+)=(.*)$/);
      if (match) {
        const keyName = match[1];
        // Check for keys that are likely API keys
        if (keyName.includes('API_KEY') || keyName.includes('SECRET')) {
          keysToRotate.push(keyName);
        }
      }
    });

    return keysToRotate;
  } catch (error) {
    console.error('Error reading environment file:', error);
    return [];
  }
}

// Generate a new key placeholder
function generateNewKey() {
  return `sk-${Math.random().toString(36).substr(2, 24)}`;
}

// Update the environment file atomically
function updateEnvFile(keyName, newKeyValue) {
  try {
    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const lines = envContent.split('\n');
    let keyFound = false;

    const updatedLines = lines.map(line => {
      const match = line.trim().match(/^([A-Z_]+)=(.*)$/);
      if (match && match[1] === keyName) {
        keyFound = true;
        return `${keyName}=${newKeyValue}`;
      }
      return line;
    });

    if (!keyFound) {
      updatedLines.push(`\n${keyName}=${newKeyValue}`);
    }

    // Write to temporary file first
    const tempFilePath = `${ENV_FILE}.tmp`;
    fs.writeFileSync(tempFilePath, updatedLines.join('\n'), 'utf8');

    // Atomically replace the original file
    fs.renameSync(tempFilePath, ENV_FILE);

    return true;
  } catch (error) {
    console.error('Error updating environment file:', error);
    return false;
  }
}

// Log the rotation event
function logRotationEvent(keyName) {
  try {
    let logData = [];

    // Read existing log if it exists
    if (fs.existsSync(LOG_FILE)) {
      const logContent = fs.readFileSync(LOG_FILE, 'utf8');
      logData = logContent ? JSON.parse(logContent) : [];
    }

    // Add new rotation event
    logData.push({
      timestamp: new Date().toISOString(),
      keyName: keyName,
      event: 'key_rotation'
    });

    // Write updated log
    fs.writeFileSync(LOG_FILE, JSON.stringify(logData, null, 2), 'utf8');
  } catch (error) {
    console.error('Error writing rotation log:', error);
  }
}

// Main function to rotate a key
function rotateKey(keyName) {
  console.log(`Rotating key: ${keyName}`);

  // Generate new key
  const newKey = generateNewKey();

  // Update environment file
  const success = updateEnvFile(keyName, newKey);

  if (success) {
    // Log the rotation event
    logRotationEvent(keyName);
    console.log(`Successfully rotated key: ${keyName}`);
    return true;
  } else {
    console.error(`Failed to rotate key: ${keyName}`);
    return false;
  }
}

module.exports = {
  rotateKey,
  getKeysForRotation
};

