// key-rotation.js

const fs = require('fs');
const path = require('path');

const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';

// Ensure log file exists
if (!fs.existsSync(LOG_FILE)) {
    fs.writeFileSync(LOG_FILE, '[]');
}

// Function to read the current environment variables from .env.test
function readEnvVariables() {
    if (!fs.existsSync(ENV_FILE)) {
        throw new Error(`Environment file ${ENV_FILE} not found.`);
    }
    const content = fs.readFileSync(ENV_FILE, 'utf8');
    const lines = content.split('\n');
    const envVars = {};
    lines.forEach(line => {
        const match = line.match(/^([^=]+)=(.*)?$/);
        if (match) {
            envVars[match[1].trim()] = match[2] ? match[2].trim() : '';
        }
    });
    return envVars;
}

// Function to write environment variables to .env.test atomically
function writeEnvVariables(envVars) {
    const tempFile = `${ENV_FILE}.tmp`;
    const lines = Object.entries(envVars).map(([key, value]) => `${key}=${value}`);
    fs.writeFileSync(tempFile, lines.join('\n'));
    fs.renameSync(tempFile, ENV_FILE);
}

// Function to log rotation event
function logRotation(keyName) {
    const logEntry = {
        timestamp: new Date().toISOString(),
        keyName: keyName
    };
    const logContent = fs.readFileSync(LOG_FILE, 'utf8');
    const logs = JSON.parse(logContent);
    logs.push(logEntry);
    fs.writeFileSync(LOG_FILE, JSON.stringify(logs, null, 2));
}

// Main function to rotate a key
function rotateKey(keyName) {
    // Read current environment variables
    const envVars = readEnvVariables();

    // Check if the key exists
    if (!envVars.hasOwnProperty(keyName)) {
        throw new Error(`Key ${keyName} not found in ${ENV_FILE}.`);
    }

    // Generate a new placeholder key
    const newKey = `NEW_PLACEHOLDER_${keyName}_VALUE`;
    envVars[keyName] = newKey;

    // Write updated environment variables atomically
    writeEnvVariables(envVars);

    // Log the rotation event
    logRotation(keyName);

    console.log(`Rotated key: ${keyName}`);
}

module.exports = { rotateKey };

