// Implements secure API key rotation mechanism

const fs = require('fs').promises;
const path = require('path');

// Configuration
const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';

/**
 * Reads the environment file and extracts key names that need rotation support
 * @returns {Promise<Array<string>>} Array of key names
 */
async function getKeyNamesForRotation() {
  try {
    const envContent = await fs.readFile(ENV_FILE, 'utf8');
    const lines = envContent.split('\n');

    // Filter lines that are variable assignments and contain 'KEY' in the name
    // but are not comments
    return lines
      .filter(line => line.trim() && !line.trim().startsWith('#'))
      .map(line => line.split('=')[0].trim())
      .filter(keyName => keyName.includes('KEY') || keyName.includes('SECRET'));
  } catch (error) {
    console.error(`Error reading ${ENV_FILE}:`, error.message);
    throw error;
  }
}

/**
 * Generates a new placeholder value for a key
 * @param {string} keyName - The name of the key
 * @returns {string} A new placeholder value
 */
function generateNewKeyPlaceholder(keyName) {
  const prefixes = {
    'ANTHROPIC': 'REDACTED_ANTHROPIC_KEY' + Date.now().toString(36),
    'STRIPE': 'REDACTED_STRIPE_LIVE' + Date.now().toString(36),
    'AWS': 'REDACTED_AWS_AKID-' + Date.now().toString(36),
    'DEFAULT': 'ROTATED-' + Date.now().toString(36)
  };

  let prefix = 'DEFAULT';
  if (keyName.includes('ANTHROPIC')) prefix = 'ANTHROPIC';
  else if (keyName.includes('STRIPE')) prefix = 'STRIPE';
  else if (keyName.includes('AWS')) prefix = 'AWS';

  return prefixes[prefix] + '-' + Math.random().toString(36).substr(2, 8);
}

/**
 * Logs the rotation event
 * @param {string} keyName - Name of the rotated key
 */
async function logRotationEvent(keyName) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    keyName: keyName,
    event: 'key_rotation'
  };

  try {
    let logs = [];
    try {
      const logContent = await fs.readFile(LOG_FILE, 'utf8');
      logs = logContent.trim() ? JSON.parse(logContent) : [];
    } catch (error) {
      // Log file doesn't exist or is empty, start with empty array
    }

    logs.push(logEntry);
    await fs.writeFile(LOG_FILE, JSON.stringify(logs, null, 2));
  } catch (error) {
    console.error('Error writing to rotation log:', error.message);
    throw error;
  }
}

/**
 * Rotates a key by generating a new placeholder and updating the environment file
 * @param {string} keyName - The name of the key to rotate
 */
async function rotateKey(keyName) {
  if (!keyName) {
    throw new Error('Key name is required');
  }

  try {
    // Read current environment file
    const envContent = await fs.readFile(ENV_FILE, 'utf8');
    const lines = envContent.split('\n');

    // Generate new key placeholder
    const newKeyPlaceholder = generateNewKeyPlaceholder(keyName);

    // Update the key value in the content
    const updatedLines = lines.map(line => {
      const trimmedLine = line.trim();
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        return line;
      }

      const [currentKey, currentValue] = line.split('=');
      if (currentKey.trim() === keyName) {
        return `${currentKey}=${newKeyPlaceholder}`;
      }

      return line;
    });

    // Write to temporary file first
    const tempFile = ENV_FILE + '.tmp';
    await fs.writeFile(tempFile, updatedLines.join('\n'));

    // Atomically replace the original file
    await fs.rename(tempFile, ENV_FILE);

    // Log the rotation event
    await logRotationEvent(keyName);

    console.log(`Successfully rotated key: ${keyName}`);
  } catch (error) {
    console.error(`Error rotating key ${keyName}:`, error.message);
    throw error;
  }
}

module.exports = {
  rotateKey,
  getKeyNamesForRotation
};

