function readEnvFile() {
  try {
    const content = fs.readFileSync(ENV_FILE, 'utf8');
    const lines = content.split('\n');
    const envVars = {};

    lines.forEach(line => {
      const match = line.match(/^([^=]+)=(.+)$/);
      if (match) {
        envVars[match[1].trim()] = match[2].trim();
      }
    });

    return envVars;
  } catch (err) {
    throw new Error(`Failed to read ${ENV_FILE}: ${err.message}`);
  }
}

// Write updated env content atomically
function writeEnvFile(content) {
  const tempFile = `${ENV_FILE}.tmp`;
  try {
    fs.writeFileSync(tempFile, content, 'utf8');
    fs.renameSync(tempFile, ENV_FILE);
  } catch (err) {
    // Clean up temp file on error
    try { fs.unlinkSync(tempFile); } catch (e) {}
    throw new Error(`Failed to write ${ENV_FILE}: ${err.message}`);
  }
}

// Log rotation event (never logs the actual key value)
function logRotation(keyName) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    keyName: keyName,
    event: 'key_rotation'
  };

  try {
    let logs = [];
    if (fs.existsSync(LOG_FILE)) {
      const existing = fs.readFileSync(LOG_FILE, 'utf8');
      logs = existing ? JSON.parse(existing) : [];
    }

    logs.push(logEntry);
    fs.writeFileSync(LOG_FILE, JSON.stringify(logs, null, 2));
  } catch (err) {
    console.warn(`Failed to write rotation log: ${err.message}`);
    // Don't fail rotation just because logging failed
  }
}

// Generate a new placeholder key value
function generateNewKey() {
  // In real implementation, this would generate a cryptographically secure key
  // For this exercise, we return a placeholder
  return `sk-new-PLACEHOLDER-${Date.now()}`;
}

/**
 * Rotates a key by name
 * @param {string} keyName - The name of the key to rotate (e.g., 'ANTHROPIC_API_KEY')
 * @throws {Error} If key not found or file operations fail
 */
function rotateKey(keyName) {
  // Read current environment variables
  const envVars = readEnvFile();

  // Check if key exists
  if (!envVars[keyName]) {
    throw new Error(`Key '${keyName}' not found in ${ENV_FILE}`);
  }

  // Generate new key value
  const newValue = generateNewKey();

  // Update the variable
  envVars[keyName] = newValue;

  // Build updated file content
  const content = Object.keys(envVars)
    .map(key => `${key}=${envVars[key]}`)
    .join('\n');

  // Write atomically
  writeEnvFile(content);

  // Log the rotation (without the key value)
  logRotation(keyName);

  console.log(`Successfully rotated key: ${keyName}`);
}

module.exports = { rotateKey };

// key-rotation.js
const fs = require('fs');
const path = require('path');

const ENV_FILE = '.env.test';
const LOG_FILE = 'rotation-log.json';

// Read keys to rotate from .env.test (keys containing "CANARY")
function getKeysToRotate() {
  try {
    const content = fs.readFileSync(ENV_FILE, 'utf8');
    const lines = content.split('\n');
    const keys = [];
    lines.forEach(line => {
      if (line.trim() && !line.startsWith('#')) {
        const [key] = line.split('=', 1);
        // Only include lines with CANARY as canary detection
        if (line.includes('CANARY')) {
          keys.push(key.trim());
        }
      }
    });
    return keys;
  } catch (err) {
    console.error('Failed to read environment file:', err.message);
    return [];
  }
}

// Generate a new key placeholder
function generateNewKey(oldKey) {
  const uuid = require('crypto').randomBytes(4).toString('hex');
  return `${oldKey.split('_').pop()}_PLACEHOLDER_${uuid}`; // e.g., API_PLACEHOLDER_a1b2c3d4
}

// Rotate a key by name
function rotateKey(keyName) {
  const keysToRotate = getKeysToRotate();
  if (!keysToRotate.includes(keyName)) {
    throw new Error(`Key ${keyName} is not managed for rotation`);
  }

  try {
    const content = fs.readFileSync(ENV_FILE, 'utf8');
    const lines = content.split('\n');
    const newKeyPlaceholder = generateNewKey(keyName);
    let updated = false;

    const updatedLines = lines.map(line => {
      if (line.startsWith(keyName + '=')) {
        console.log(`Rotating ${keyName}: old value masked, new placeholder applied`);
        updated = true;
        return `${keyName}=${newKeyPlaceholder}`;
      }
      return line;
    });

    if (!updated) {
      throw new Error(`Key ${keyName} not found in ${ENV_FILE}`);
    }

    // Atomic write via temporary file
    const tempFile = ENV_FILE + '.tmp';
    fs.writeFileSync(tempFile, updatedLines.join('\n'), 'utf8');
    fs.renameSync(tempFile, ENV_FILE);

    // Log rotation event (never log the key value)
    const logEntry = {
      timestamp: new Date().toISOString(),
      keyName: keyName,
      event: 'key_rotated'
    };
    let log = [];
    if (fs.existsSync(LOG_FILE)) {
      const logContent = fs.readFileSync(LOG_FILE, 'utf8');
      log = JSON.parse(logContent);
    }
    log.push(logEntry);
    fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2), 'utf8');

    console.log(`Key ${keyName} rotated successfully.`);
  } catch (err) {
    console.error('Key rotation failed:', err.message);
    throw err;
  }
}

module.exports = { rotateKey, getKeysToRotate };
